class Solution {
    public boolean isRationalEqual(String s, String t) {
        return Math.abs(parse(s) - parse(t)) < 1e-9;
    }
    private double parse(String s) {
        int lparen = s.indexOf('(');
        if (lparen < 0) return Double.parseDouble(s);
        String base = s.substring(0, lparen);
        String rep = s.substring(lparen + 1, s.length() - 1);
        StringBuilder sb = new StringBuilder(base);
        for (int i = 0; i < 20; i++) sb.append(rep);
        return Double.parseDouble(sb.toString());
    }
}

class Solution {
    public boolean isRationalEqual(String s, String t) {
        long[] f1 = toFraction(s);
        long[] f2 = toFraction(t);
        return f1[0] * f2[1] == f1[1] * f2[0];
    }
    private long[] toFraction(String s) {
        int dotIdx = s.indexOf('.');
        int lp = s.indexOf('(');
        if (dotIdx < 0) {
            return new long[]{Long.parseLong(s), 1};
        }
        String intPart = s.substring(0, dotIdx);
        String nonRep = lp < 0 ? s.substring(dotIdx + 1) : s.substring(dotIdx + 1, lp);
        String rep = lp < 0 ? "" : s.substring(lp + 1, s.length() - 1);
        long intVal = intPart.isEmpty() ? 0 : Long.parseLong(intPart);
        long nonRepVal = nonRep.isEmpty() ? 0 : Long.parseLong(nonRep);
        int nonRepLen = nonRep.length();
        if (rep.isEmpty()) {
            long den = 1;
            for (int i = 0; i < nonRepLen; i++) den *= 10;
            long num = intVal * den + nonRepVal;
            long g = gcd(Math.abs(num), den);
            return new long[]{num / g, den / g};
        }
        long repVal = Long.parseLong(rep);
        int repLen = rep.length();
        long nines = 1;
        for (int i = 0; i < repLen; i++) nines *= 10;
        nines -= 1;
        long pow10 = 1;
        for (int i = 0; i < nonRepLen; i++) pow10 *= 10;
        long den = nines * pow10;
        long num = intVal * den + nonRepVal * nines + repVal;
        long g = gcd(Math.abs(num), den);
        return new long[]{num / g, den / g};
    }
    private long gcd(long a, long b) {
        while (b != 0) { long t = b; b = a % b; a = t; }
        return a;
    }
}
